using System;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : TestMethodAttribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

public abstract class TimedTestBase
{
    private System.Diagnostics.Stopwatch? _stopwatch;

    public TestContext TestContext { get; set; } = null!;

    [TestInitialize]
    public void TimedTestInitialize()
    {
        _stopwatch = System.Diagnostics.Stopwatch.StartNew();
    }

    [TestCleanup]
    public void TimedTestCleanup()
    {
        if (_stopwatch is null) return;
        _stopwatch.Stop();

        var method = GetType().GetMethod(TestContext.TestName!);
        var attr = method?.GetCustomAttributes(typeof(TimedTestMethodAttribute), false);
        if (attr is { Length: > 0 })
        {
            var threshold = ((TimedTestMethodAttribute)attr[0]).WarningThresholdMs;
            if (_stopwatch.ElapsedMilliseconds > threshold)
            {
                Console.WriteLine($"WARNING: {TestContext.TestName} took {_stopwatch.ElapsedMilliseconds}ms (threshold: {threshold}ms)");
            }
        }
    }
}

